class Solution {
    static const long long MOD=1000000007LL;
    vector<long long> sum,square,lazy;
    void apply(int node,int left,int right,long long add){
        long long length=right-left+1LL;
        square[node]=(square[node]+2*add%MOD*sum[node]%MOD+add*add%MOD*length%MOD)%MOD;
        sum[node]=(sum[node]+add*length)%MOD;
        lazy[node]+=add;
    }
    void push(int node,int left,int right){
        long long add=lazy[node];
        if(!add||left==right)return;
        int middle=(left+right)/2;
        apply(node*2,left,middle,add);
        apply(node*2+1,middle+1,right,add);
        lazy[node]=0;
    }
    void update(int node,int left,int right,int queryLeft,int queryRight){
        if(queryLeft<=left&&right<=queryRight){
            apply(node,left,right,1);
            return;
        }
        push(node,left,right);
        int middle=(left+right)/2;
        if(queryLeft<=middle)update(node*2,left,middle,queryLeft,queryRight);
        if(queryRight>middle)update(node*2+1,middle+1,right,queryLeft,queryRight);
        sum[node]=(sum[node*2]+sum[node*2+1])%MOD;
        square[node]=(square[node*2]+square[node*2+1])%MOD;
    }
    public:int sumCounts(vector<int>& nums){
        int n=nums.size();
        sum.assign(4*n,0);
        square.assign(4*n,0);
        lazy.assign(4*n,0);
        unordered_map<int,int> last;
        long long answer=0;
        for(int index=0;index<n;++index){
            auto found=last.find(nums[index]);
            int previous=found==last.end()?-1:found->second;
            update(1,0,n-1,previous+1,index);
            answer=(answer+square[1])%MOD;
            last[nums[index]]=index;
        }
        return answer;
    }
};
